-- Traduccions (es, en) dels textos desats en català: campanyes i avisos del padró.
-- El panell les fa servir quan l'amo el té en castellà o en anglès; el que no hi és, surt en català.
-- Font: src/lib/data/traduccions-db.ts (els seeds les desen igual).
alter table public.campaigns add column if not exists i18n jsonb not null default '{}'::jsonb;
alter table public.ingredient_alerts add column if not exists i18n jsonb not null default '{}'::jsonb;

update public.campaigns set i18n = '{"es":{"title":"Recupera {{n}} habituales","chips":["{{n}} clientes","Venían 1-2 veces por semana","Más de 14 días sin venir","{{a_mig}} con el carnet a medias"],"reasons":["Son el {{pct_clients}} de los clientes pero hacían el **{{pct_comandes}} de los pedidos con carnet**. Los últimos 3 meses gastaron unos {{cost}} al mes.","A {{a_mig}} de los {{n}} les faltan 3 palabras o menos para completar el carnet. Es el mejor gancho: no hace falta ningún descuento.","La última recuperación hizo volver al **{{tornat}}** en 14 días. Sin aviso, solo volvió el {{control}}."],"schedule_text":"Jueves a las 11:30.","schedule_reason":"Es cuando este grupo suele decidir dónde come.","proposed_label":"Propuesta hoy a las 6:00","simpler_label":"Sin mencionar el padró"},"en":{"title":"Win back {{n}} regulars","chips":["{{n}} customers","Came 1-2 times a week","Over 14 days without coming","{{a_mig}} with the card half full"],"reasons":["They''re {{pct_clients}} of customers but placed **{{pct_comandes}} of card orders**. Over the last 3 months they spent about {{cost}} a month.","{{a_mig}} of the {{n}} are 3 words or fewer from completing the card. That''s the best hook: no discount needed.","The last win-back brought back **{{tornat}}** within 14 days. Without a message, only {{control}} came back."],"schedule_text":"Thursday at 11:30.","schedule_reason":"That''s when this group usually decides where to have lunch.","proposed_label":"Proposed today at 6:00","simpler_label":"Without mentioning the padró"}}'::jsonb where slug = 'recupera-habituals';
update public.campaigns set i18n = '{"es":{"title":"Llega la alcachofa del Prat","chips":["{{bolets_n}} clientes","Recibieron el aviso de las setas","Alta en el padró"],"reasons":["El aviso de las setas empadronadas hizo volver al **{{bolets_tornat}}** en 14 días.","Los {{bolets_n}} que lo recibieron son el público natural de un ingrediente nuevo.","No hay ninguna promoción: el alta en el padró ya es la noticia."],"schedule_text":"El día del alta, a las 10:00.","schedule_reason":"Antes de que se decida la comida.","proposed_label":"Propuesta ayer"},"en":{"title":"The Prat artichoke is arriving","chips":["{{bolets_n}} customers","Got the mushroom message","Joins the padró"],"reasons":["The message about the mushrooms joining the padró brought back **{{bolets_tornat}}** within 14 days.","The {{bolets_n}} who got it are the natural audience for a new ingredient.","There''s no promotion: joining the padró is the news."],"schedule_text":"On the day it joins, at 10:00.","schedule_reason":"Before people decide on lunch.","proposed_label":"Proposed yesterday"}}'::jsonb where slug = 'carxofa';
update public.campaigns set i18n = '{"es":{"title":"Bienvenida a los nuevos del verano"},"en":{"title":"Welcome to summer''s newcomers"}}'::jsonb where slug = 'benvinguda-estiu';
update public.campaigns set i18n = '{"es":{"title":"Recuperación de septiembre"},"en":{"title":"September win-back"}}'::jsonb where slug = 'recuperacio-setembre';
update public.campaigns set i18n = '{"es":{"title":"Setas empadronadas"},"en":{"title":"Mushrooms join the padró"}}'::jsonb where slug = 'bolets';
update public.ingredient_alerts set i18n = '{"es":{"title":"La alcachofa del Prat pide empadronarse","reasons":["En el calendario de temporada, la alcachofa del Prat entra el **{{alta}}**.","Puede entrar en el Fes-te''l tu como guarnición sin tocar ningún plato de la casa.","Ya tienes preparada la campaña para quienes recibieron el aviso de las setas."]},"en":{"title":"The Prat artichoke wants to join the padró","reasons":["On the seasonal calendar, the Prat artichoke comes in on **{{alta}}**.","It can go into Fes-te''l tu as a side without changing any house dish.","The campaign for people who got the mushroom message is ready."]}}'::jsonb where id = 'alta-carxofa';
update public.ingredient_alerts set i18n = '{"es":{"title":"El tomate se da de baja","reasons":["La temporada de proximidad se acaba el **{{baixa}}**.","Solo afecta a L''Esqueixat, que ya baja con la llegada del otoño.","No hace falta avisar a nadie con una campaña: basta con el anuncio en la web."]},"en":{"title":"Tomatoes leave the padró","reasons":["The local season ends on **{{baixa}}**.","It only affects L''Esqueixat, which is already dropping now that autumn is here.","No campaign needed: the announcement on the website is enough."]}}'::jsonb where id = 'baixa-tomaquet';
